import itertools
from collections import deque

def has_short_cycle(adj, n, max_cycle_len=7):
    """Check if graph has any cycle of length <= max_cycle_len"""
    # Check for cycles of length 3 to max_cycle_len
    for cycle_len in range(3, max_cycle_len + 1):
        if has_cycle_of_length(adj, n, cycle_len):
            return True
    return False

def has_cycle_of_length(adj, n, length):
    """Check if there's a cycle of exactly the given length"""
    # BFS from each vertex to find cycles
    for start in range(n):
        # BFS with path tracking
        queue = deque([(start, [start])])
        visited_at_depth = {start: 0}

        while queue:
            node, path = queue.popleft()

            if len(path) > length:
                continue

            for neighbor in adj[node]:
                if neighbor == start and len(path) == length:
                    return True
                if neighbor not in path and len(path) < length:
                    if neighbor not in visited_at_depth or visited_at_depth[neighbor] > len(path):
                        visited_at_depth[neighbor] = len(path)
                        queue.append((neighbor, path + [neighbor]))

    return False

def is_k_colorable(adj, n, k):
    """Check if graph is k-colorable using backtracking"""
    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        for c in range(k):
            valid = True
            for neighbor in adj[v]:
                if neighbor < v and colors[neighbor] == c:
                    valid = False
                    break
            if valid:
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

