from collections import deque
import itertools
import random

def has_cycle_of_length_le(adj, n, max_len):
    """Check if graph has any cycle of length <= max_len using BFS from each vertex"""
    for start in range(n):
        # BFS from start, tracking distance
        dist = {start: 0}
        parent = {start: -1}
        queue = deque([start])

        while queue:
            node = queue.popleft()

            for neighbor in adj[node]:
                if neighbor not in dist:
                    dist[neighbor] = dist[node] + 1
                    parent[neighbor] = node
                    queue.append(neighbor)
                elif neighbor != parent[node]:
                    # Found a cycle
                    cycle_len = dist[node] + dist[neighbor] + 1
                    if cycle_len <= max_len:
                        return True

    return False

